-- ============================================================
-- Import batch KETIGA: 2 Sprin baru (7 September 2026) dari
-- C:\Database SPRIN SIandi\part 3\ -- GATUR harian + UNRAS DPRD & Pemkab KBB.
-- jabatan_operasional kali ini diisi PERSIS dari kolom OPERASIONAL dokumen
-- asli (PADAL/KATIM/DANTON/nama pos, dst), tidak lagi disamakan dengan nama
-- kelompok -- fidelitas lebih tinggi dari batch sebelumnya.
--
-- 425 baris penempatan personel. Semua NRP tervalidasi terhadap roster
-- (4 koreksi transkripsi ditemukan lewat pencocokan nama), plus 3 perwira
-- (PAMA Polres Cimahi, MOCH. ERIK RAMDHAN / AWALUDIN ABD MALIK / M. GARIZ
-- LUIS MA'LUF) dan 2 ASN Dokkes yang belum ada di snapshot KUATPERS --
-- masuk lewat personel_non_kuatpers.
--
-- Tidak butuh jenis_kegiatan baru (PENGAMANAN KEGIATAN LAINNYA & PENGAMANAN
-- UNJUK RASA sudah ada). Tidak idempoten sepenuhnya -- JANGAN dijalankan dua kali.
-- ============================================================

alter table public.surat_perintah disable trigger trg_surat_perintah_before_write;

insert into public.surat_perintah (
  nomor_agenda, nomor_lengkap, jenis_kegiatan_id, perihal, pertimbangan, lokasi,
  tanggal_mulai, tanggal_selesai, jam_apel, butir_untuk,
  status, disusun_oleh, disetujui_oleh, disetujui_pada
)
select
  x.nomor_agenda, x.nomor_lengkap, jk.id, x.perihal, x.pertimbangan, x.lokasi,
  x.tanggal_mulai::date, x.tanggal_selesai::date, nullif(x.jam_apel,'')::time,
  case when x.butir_untuk is null then null
    else array(select jsonb_array_elements_text(x.butir_untuk::jsonb)) end,
  'TERBIT'::status_surat_perintah,
  (select id from public.pengguna where nrp = '87121335'),
  (select id from public.pengguna where nrp = '76010326'),
  x.tanggal_mulai::date::timestamptz
from jsonb_to_recordset('[{"kode":"sprin2080","nomor_agenda":2080,"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","jenis_kegiatan_nama":"PENGAMANAN KEGIATAN LAINNYA","perihal":"Pengaturan Lalu Lintas Pagi dan Sore di Wilayah Hukum Polres Cimahi","pertimbangan":"bahwa dalam rangka antisipasi kerawanan kamtibmas, penggelaran kekuatan dan pengaturan lalu lintas pagi dan sore hari di wilayah hukum Polres Cimahi, maka dipandang perlu mengeluarkan surat perintah ini.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-09-07","tanggal_selesai":"2026-09-07","jam_apel":"06:00","butir_untuk":"[\"disamping tugas dan tanggung jawab sehari-hari, ditunjuk untuk melaksanakan penjagaan dan pengaturan lalu lintas pada hari Senin tanggal 07 September 2026, pukul 06.00 sd 07.30 WIB dan/atau menyesuaikan jam rawan macet di wilayah hukum Polres Cimahi;\",\"personel menggunakan pakaian PDL II Two tone/PDL Lantas;\",\"Kasat Lantas, Kasat Samapta dan para Kapolsek agar melaksanakan pengawasan dan pengendalian serta bertanggung jawab atas kehadiran anggotanya;\",\"melaksanakan perintah ini dengan seksama dan penuh rasa tanggung jawab;\",\"melaporkan hasil pelaksanaan tugas kepada Ka / Waka / Kabag Ops Polres Cimahi pada kesempatan pertama.\"]"},{"kode":"sprin2081","nomor_agenda":2081,"nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","jenis_kegiatan_nama":"PENGAMANAN UNJUK RASA","perihal":"Pengamanan Kegiatan Aksi Unjuk Rasa di Kantor Bupati dan Kantor DPRD Kab. Bandung Barat","pertimbangan":"bahwa dalam rangka mendukung Pengamanan Kegiatan Aksi Unjuk Rasa di wilayah Kota Cimahi, maka dipandang perlu mengeluarkan surat perintah ini.","lokasi":"Kantor Pemkab Bandung Barat, Jalan Raya Padalarang-Cisarua KM 2, Desa Mekarsari, Kec. Ngamprah, Kab. Bandung Barat","tanggal_mulai":"2026-09-07","tanggal_selesai":"2026-09-07","jam_apel":"08:00","butir_untuk":"[\"melaksanakan Pengamanan Kegiatan Aksi Unjuk Rasa di Kantor Bupati dan Kantor DPRD Kab. Bandung Barat;\",\"apel kesiapan kegiatan pengamanan dilaksanakan pada hari Senin tanggal 07 September 2026 pukul 08.00 WIB bertempat di Kantor Pemkab Bandung Barat dipimpin oleh KAPOLRES CIMAHI;\",\"seluruh personel DILARANG MEMBAWA / MENGGUNAKAN SENJATA API dalam pelaksanaan tugas pengamanan;\",\"personel menggunakan pakaian PDL II Two tone/menyesuaikan;\",\"melaksanakan perintah ini dengan saksama dan penuh rasa tanggung jawab;\",\"melaporkan hasil pelaksanaan kegiatan kepada KA / Waka / Kabag Ops Polres Cimahi pada kesempatan pertama.\"]"}]'::jsonb) as x(
  kode text, nomor_agenda int, nomor_lengkap text, jenis_kegiatan_nama text, perihal text,
  pertimbangan text, lokasi text, tanggal_mulai text, tanggal_selesai text, jam_apel text,
  butir_untuk text
)
join public.jenis_kegiatan jk on jk.nama = x.jenis_kegiatan_nama
where not exists (select 1 from public.surat_perintah sp where sp.nomor_lengkap = x.nomor_lengkap);

alter table public.surat_perintah enable trigger trg_surat_perintah_before_write;

insert into public.dasar_hukum_rujukan (surat_perintah_id, perihal, jenis_dokumen)
select sp.id, x.perihal, x.jenis_dokumen
from jsonb_to_recordset('[{"nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","perihal":"Infosus Sat Intelkam Polres Cimahi Nomor R/Infosus/282/IX/2026/Intelkam tanggal 06 September 2026 tentang rencana Kegiatan Aksi Unjuk Rasa dari Presedium Gerakan Organisasi Masyarakat Kab. Bandung Barat dan Forum RT-RW Kab. Bandung Barat","jenis_dokumen":"Rujukan"}]'::jsonb) as x(nomor_lengkap text, perihal text, jenis_dokumen text)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap;


insert into public.sprin_kelompok (surat_perintah_id, jenis_kegiatan_kelompok_id, nama_kelompok, kelompok_besar, sifat, urutan)
select
  sp.id, jkk.id, x.nama_kelompok, x.kelompok_besar,
  coalesce(jkk.sifat, case when x.nama_kelompok in ('UNSUR PIMPINAN', 'PIM STAF', 'PIMPINAN') then 'PENGENDALI' else 'PELAKSANA' end::sifat_kelompok),
  x.urutan
from jsonb_to_recordset('[{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"PIM STAF","kelompok_besar":null,"urutan":0},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"SAT LANTAS","kelompok_besar":null,"urutan":1},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"SAT SAMAPTA","kelompok_besar":null,"urutan":2},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK LEMBANG","kelompok_besar":null,"urutan":3},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CISARUA","kelompok_besar":null,"urutan":4},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CIMAHI","kelompok_besar":null,"urutan":5},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK PADALARANG","kelompok_besar":null,"urutan":6},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CIPATAT","kelompok_besar":null,"urutan":7},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CIPEUNDEUY","kelompok_besar":null,"urutan":8},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CIKAWET","kelompok_besar":null,"urutan":9},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CIMAHI SELATAN","kelompok_besar":null,"urutan":10},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK MARGAASIH","kelompok_besar":null,"urutan":11},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK BATUJAJAR","kelompok_besar":null,"urutan":12},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK CILILIN","kelompok_besar":null,"urutan":13},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK SINDANGKERTA","kelompok_besar":null,"urutan":14},{"nomor_lengkap":"SPRIN/2080/IX/PAM.3.3./2026","nama_kelompok":"WILAYAH POLSEK GUNUNGHALU","kelompok_besar":null,"urutan":15},{"nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","nama_kelompok":"PIM STAF","kelompok_besar":null,"urutan":0},{"nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","nama_kelompok":"PAM OBJEK KANTOR PEMKAB BANDUNG BARAT","kelompok_besar":null,"urutan":1},{"nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","nama_kelompok":"PAM OBJEK KANTOR DPRD KAB. BANDUNG BARAT","kelompok_besar":null,"urutan":2}]'::jsonb) as x(nomor_lengkap text, nama_kelompok text, kelompok_besar text, urutan int)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap
left join public.jenis_kegiatan_kelompok jkk
  on jkk.jenis_kegiatan_id = sp.jenis_kegiatan_id and upper(jkk.nama_kelompok) = upper(x.nama_kelompok);


