  nrp_aktif text, nomor_urut_keseluruhan int, nomor_urut_kelompok int, jabatan_operasional text,
  nomor_lengkap text, kelompok_besar text, nama_kelompok text
)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap
join public.sprin_kelompok sk
  on sk.surat_perintah_id = sp.id
  and sk.nama_kelompok = x.nama_kelompok
  and coalesce(sk.kelompok_besar,'') = coalesce(x.kelompok_besar,'')
join public.pengguna pg on pg.nrp = x.nrp_aktif;


insert into public.sprin_personel (sprin_kelompok_id, personel_non_kuatpers_id, nomor_urut_keseluruhan, nomor_urut_kelompok, jabatan_operasional)
select
  sk.id, nk.id, x.nomor_urut_keseluruhan, x.nomor_urut_kelompok, x.jabatan_operasional
from jsonb_to_recordset('[{"nrp_aktif":"86061546","nonKuatpers":true,"nomor_urut_keseluruhan":73,"nomor_urut_kelompok":63,"jabatan_operasional":"DANTON 3 DALMAS AWAL","nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"PAM OBJEK KANTOR PEMKAB BANDUNG BARAT"},{"nrp_aktif":"197701292006042003","nonKuatpers":true,"nomor_urut_keseluruhan":118,"nomor_urut_kelompok":108,"jabatan_operasional":"ANGGOTA","nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"PAM OBJEK KANTOR PEMKAB BANDUNG BARAT"},{"nrp_aktif":"90060182","nonKuatpers":true,"nomor_urut_keseluruhan":183,"nomor_urut_kelompok":62,"jabatan_operasional":"DANTON 3 DALMAS AWAL","nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"PAM OBJEK KANTOR DPRD KAB. BANDUNG BARAT"},{"nrp_aktif":"94090102","nonKuatpers":true,"nomor_urut_keseluruhan":203,"nomor_urut_kelompok":82,"jabatan_operasional":"DANTON DALMAS LANJUT","nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"PAM OBJEK KANTOR DPRD KAB. BANDUNG BARAT"},{"nrp_aktif":"199105252022022000","nonKuatpers":true,"nomor_urut_keseluruhan":240,"nomor_urut_kelompok":119,"jabatan_operasional":"ANGGOTA","nomor_lengkap":"SPRIN/2081/IX/PAM.3.2./2026","kelompok_besar":null,"nama_kelompok":"PAM OBJEK KANTOR DPRD KAB. BANDUNG BARAT"}]'::jsonb) as x(
  nrp_aktif text, nomor_urut_keseluruhan int, nomor_urut_kelompok int, jabatan_operasional text,
  nomor_lengkap text, kelompok_besar text, nama_kelompok text
)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap
join public.sprin_kelompok sk
  on sk.surat_perintah_id = sp.id
  and sk.nama_kelompok = x.nama_kelompok
  and coalesce(sk.kelompok_besar,'') = coalesce(x.kelompok_besar,'')
join public.personel_non_kuatpers nk on nk.nrp = x.nrp_aktif;


-- Verifikasi jumlah baris:
select
  (select count(*) from public.surat_perintah where nomor_lengkap in ('SPRIN/2080/IX/PAM.3.3./2026','SPRIN/2081/IX/PAM.3.2./2026')) as sprin_masuk,
  (select count(*) from public.sprin_kelompok sk join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/2080/IX/PAM.3.3./2026','SPRIN/2081/IX/PAM.3.2./2026')) as kelompok_masuk,
  (select count(*) from public.sprin_personel spr join public.sprin_kelompok sk on sk.id=spr.sprin_kelompok_id join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/2080/IX/PAM.3.3./2026','SPRIN/2081/IX/PAM.3.2./2026')) as personel_masuk;
